lessons.push(...[{"id": "exp-20261102b-01", "subject": "商業簿記", "topic": "引当金", "title": "貸倒懸念債権の財務内容評価法", "body": "貸倒懸念債権は、担保・保証による回収見込額を差し引いた残額について債務者の支払能力を検討し、回収不能見込額を引き当てます。例：債権1,000,000円、担保・保証の回収見込400,000円、残額の回収可能割合50％なら貸倒見積額は（1,000,000−400,000）×50％＝300,000円。既存引当金が同一債権について100,000円なら追加繰入は200,000円です。", "tag": "商業簿記｜引当金", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=109", "sourceLabel": "公式基準・出題区分表", "reviewed": "2026-11-02", "years": [2026, 2027]}, {"id": "exp-20261102b-02", "subject": "会計学", "topic": "引当金", "title": "債権区分と貸倒見積り", "body": "債権は債務者の状態に応じ一般債権・貸倒懸念債権・破産更生債権等に区分し、回収不能の見積方法を区別します。一般債権は原則として貸倒実績率等、貸倒懸念債権は財務内容評価法またはキャッシュ・フロー見積法、破産更生債権等は担保・保証による回収見込額等を控除した残額を用います。個別の状況を確認し、全債権に同じ率を無条件に使わないことが大切です。", "tag": "会計学｜引当金", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=109", "sourceLabel": "公式基準・出題区分表", "reviewed": "2026-11-02", "years": [2026, 2027]}, {"id": "exp-20261102b-03", "subject": "工業簿記", "topic": "工原：実際総合原価計算", "title": "正常仕損と異常仕損の負担", "body": "正常仕損は通常の製造過程で避けられない仕損、異常仕損は想定外の原因で生じる仕損です。設例では材料を始点投入、月初・月末仕掛品なし、仕損は完成時発見、処分価値なしとします。投入100個、正常仕損10個、完成90個、原価90,000円なら正常仕損費を完成品に負担させ、完成品単価は90,000÷90＝1,000円。仕損品の原価を別途加算すると二重計算です。", "tag": "工業簿記｜総合原価計算", "sourceUrl": "https://www.kentei.ne.jp/wp/wp-content/uploads/2021/12/2022_kogen.pdf", "sourceLabel": "公式基準・出題区分表", "reviewed": "2026-11-02", "years": [2026, 2027]}, {"id": "exp-20261102b-04", "subject": "原価計算", "topic": "工原：実際総合原価計算", "title": "正常仕損の処分価値", "body": "正常仕損品に処分価値がある場合、設例でその収入を正常仕損費から控除します。材料始点投入、月初・月末仕掛品なし、完成時発見、投入100個、正常仕損10個、完成90個、製造原価100,000円、処分価値合計10,000円なら、完成品原価は100,000−10,000＝90,000円、単価1,000円です。発生点や月末仕掛品の条件が変わると配分も変わります。", "tag": "原価計算｜総合原価計算", "sourceUrl": "https://www.kentei.ne.jp/wp/wp-content/uploads/2021/12/2022_kogen.pdf", "sourceLabel": "公式基準・出題区分表", "reviewed": "2026-11-02", "years": [2026, 2027]}]);
qs.push(...[{"id": "exp-q-20261102b-01", "subject": "商業簿記", "topic": "引当金", "q": "貸倒懸念債権2,000,000円、担保回収見込800,000円、残額のうち回収不能割合25％。当該債権の期首引当金100,000円、他の増減なし。決算整理仕訳は？", "a": ["借：貸倒引当金繰入200,000／貸：貸倒引当金200,000", "借：貸倒引当金繰入300,000／貸：貸倒引当金300,000", "借：貸倒引当金100,000／貸：貸倒引当金戻入100,000"], "correct": 0, "ex": "必要額＝（2,000,000−800,000）×25％＝300,000円。追加繰入＝300,000−100,000＝200,000円。", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=109", "sourceLabel": "公式基準・出題区分表", "reviewed": "2026-11-02", "years": [2026, 2027]}, {"id": "exp-q-20261102b-02", "subject": "会計学", "topic": "引当金", "q": "破産更生債権等1,500,000円のうち担保・保証で500,000円回収見込み、他の回収見込みはない。必要な貸倒見積額は？", "a": ["1,000,000円", "500,000円", "1,500,000円"], "correct": 0, "ex": "債権1,500,000−担保・保証の回収見込500,000＝1,000,000円。条件上、残額は回収不能として見積もります。", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=109", "sourceLabel": "公式基準・出題区分表", "reviewed": "2026-11-02", "years": [2026, 2027]}, {"id": "exp-q-20261102b-03", "subject": "工業簿記", "topic": "工原：実際総合原価計算", "q": "月初・月末仕掛品なし、材料始点投入、完成時に正常仕損20個、完成180個。原価180,000円、仕損品処分価値なし。正常仕損費を完成品に負担させた完成品単価は？", "a": ["1,000円", "900円", "1,100円"], "correct": 0, "ex": "投入は180＋20＝200個。正常仕損費は完成品に含め、180,000÷180＝1,000円。", "sourceUrl": "https://www.kentei.ne.jp/wp/wp-content/uploads/2021/12/2022_kogen.pdf", "sourceLabel": "公式基準・出題区分表", "reviewed": "2026-11-02", "years": [2026, 2027]}, {"id": "exp-q-20261102b-04", "subject": "原価計算", "topic": "工原：実際総合原価計算", "q": "月初・月末仕掛品なし、材料始点投入、完成時に正常仕損10個、完成90個。製造原価110,000円、仕損品の処分価値合計11,000円。処分価値を控除後の完成品総原価は？", "a": ["99,000円", "110,000円", "121,000円"], "correct": 0, "ex": "仕損品の処分価値を控除し、110,000−11,000＝99,000円。完成品単価は99,000÷90＝1,100円。", "sourceUrl": "https://www.kentei.ne.jp/wp/wp-content/uploads/2021/12/2022_kogen.pdf", "sourceLabel": "公式基準・出題区分表", "reviewed": "2026-11-02", "years": [2026, 2027]}]);
